insert into public.traduzioni_ui(namespace,chiave,it,de,fr,en,rm) values
('onboarding','avvio.titolo','Avvio del club','Start des Clubs','Démarrage du club','Club start-up','Avvio dal club'),
('onboarding','avvio.sottotitolo','Quello che serve perché il club possa lavorare','Was der Club braucht, um arbeiten zu können','Ce qu''il faut pour que le club puisse travailler','What the club needs before it can operate','Quai che il club dovra per pudair lavurar'),
('onboarding','avvio.nessun_club','Nessun club è collegato a questa sessione. Esci e rientra, poi riprova.','Mit dieser Sitzung ist kein Club verbunden. Melden Sie sich ab und wieder an und versuchen Sie es erneut.','Aucun club n''est lié à cette session. Déconnectez-vous, reconnectez-vous, puis réessayez.','No club is linked to this session. Sign out, sign back in, then try again.','Nagin club n''è collià cun questa sessiun. Sortai e turnai, lura empruvai anc ina giada.'),
('onboarding','avvio.errore_titolo','L''elenco dei controlli non è disponibile','Die Liste der Prüfungen ist nicht verfügbar','La liste des contrôles n''est pas disponible','The list of checks isn''t available','La glista da las controllas n''è betg disponibla'),
('onboarding','avvio.errore_dettaglio','Non significa che non ci sia lavoro in sospeso: semplicemente non sono riuscito a leggerlo.','Das heisst nicht, dass nichts offen ist: Die Liste konnte nur nicht gelesen werden.','Cela ne veut pas dire qu''il n''y a rien en suspens : la liste n''a simplement pas pu être lue.','This doesn''t mean nothing is pending: the list simply couldn''t be read.','Quai na munta betg ch''i na dettia nagina lavur pendenta: la glista n''ha simplamain betg pudì vegnir legida.'),
('onboarding','avvio.errore_lettura','Lettura dei controlli di avvio non riuscita','Die Start-Prüfungen konnten nicht gelesen werden','Impossible de lire les contrôles de démarrage','The start-up checks couldn''t be read','Las controllas d''avvio n''han betg pudì vegnir legidas'),
('onboarding','avvio.riprova','Riprova','Erneut versuchen','Réessayer','Try again','Empruvar anc ina giada'),
('onboarding','avvio.a_posto','{{a_posto}} di {{totale}} a posto','{{a_posto}} von {{totale}} erledigt','{{a_posto}} sur {{totale}} en ordre','{{a_posto}} of {{totale}} done','{{a_posto}} da {{totale}} en urden'),
('onboarding','avvio.bloccanti_one','C''è 1 controllo bloccante da risolvere: il club non è pronto a lavorare finché non è a posto.','1 blockierende Prüfung ist offen: Der Club ist erst arbeitsbereit, wenn sie erledigt ist.','1 contrôle bloquant reste à résoudre : le club ne peut pas travailler tant qu''il n''est pas réglé.','1 blocking check is still open: the club can''t operate until it''s resolved.','I dat 1 controlla che blochescha: il club n''è betg pront da lavurar fin ch''ella n''è betg en urden.'),
('onboarding','avvio.bloccanti_other','Ci sono {{count}} controlli bloccanti da risolvere: il club non è pronto a lavorare finché non sono a posto.','{{count}} blockierende Prüfungen sind offen: Der Club ist erst arbeitsbereit, wenn sie erledigt sind.','{{count}} contrôles bloquants restent à résoudre : le club ne peut pas travailler tant qu''ils ne sont pas réglés.','{{count}} blocking checks are still open: the club can''t operate until they''re resolved.','I dat {{count}} controllas che blocheschan: il club n''è betg pront da lavurar fin ch''ellas n''èn betg en urden.'),
('onboarding','avvio.vai_alla_lista','Vai alla lista di avvio','Zur Start-Liste','Aller à la liste de démarrage','Go to the start-up list','Ir a la glista d''avvio'),
